import { generateLuaWzKey } from "../util/WzKeyGenerator.js";
import { WzImageProperty } from "../WzImageProperty.js";
import { WzPropertyType } from "../WzPropertyType.js";
import { asciiTextDecoder } from "../util/node.js";
/**
 * @public
 */
export class WzLuaProperty extends WzImageProperty {
    constructor(name, encryptedBytes) {
        super();
        this.name = name;
        this.encryptedBytes = encryptedBytes;
        this.parent = null;
        this.wzKey = generateLuaWzKey();
    }
    setValue(value) {
        this.encryptedBytes = value;
    }
    get wzValue() {
        return this.value;
    }
    get value() {
        return this.encryptedBytes;
    }
    get propertyType() {
        return WzPropertyType.Lua;
    }
    toString() {
        if (this.encryptedBytes == null)
            return '';
        return asciiTextDecoder.decode(this.encodeDecode(this.encryptedBytes));
    }
    encodeDecode(input) {
        const newArray = new Uint8Array(input.length);
        for (let i = 0; i < input.length; i++) {
            const encryptedChar = ((input[i] ^ this.wzKey.at(i)) & 0xFF);
            newArray[i] = encryptedChar;
        }
        return newArray;
    }
    dispose() {
        if (this._disposed)
            return;
        this.encryptedBytes = null;
        this._disposed = true;
    }
}
